/**
 * Abuse protection for every Claude-backed route (docs/design-plan.md §11):
 * - Rate limits (sliding window): 20/min per anon ID, 60/min per IP.
 * - Daily spend caps (UTC day, micro-USD): $5 per anon ID, $25 per IP, $75 global.
 *
 * Failure policy when storage misbehaves (decided by Dinakar, 2026-10-17): everything fails OPEN.
 * Limits are a safeguard, not a product requirement, so a broken counter must never block learners.
 * Instead the request proceeds with a `warning` the UI shows ("let the tool's owner know"), and
 * `limitsStatus()` reports the degradation (surfaced by /api/health).
 */
import type Anthropic from "@anthropic-ai/sdk";
import type { Store, UsageScope } from "@/lib/contracts/store";
import { getStore, storeKind } from "@/lib/store";
import { upstashCredentials } from "@/lib/store/redis-kv";
import { redactError } from "@/lib/store/errors";
import { estimateCostMicroUsd, type UsageLike } from "./cost";
import { MemoryRateLimiter, upstashRateLimiter, type RateLimiter } from "./ratelimit";

export { estimateCostMicroUsd } from "./cost";

export type LimitCheck =
  | { ok: true; warning?: string }
  | { ok: false; code: "rate_limited" | "spend_cap"; message: string; retryAfterS?: number };

export const RATE_LIMITS = {
  anon: { max: 20, windowS: 60 },
  ip: { max: 60, windowS: 60 },
} as const;

export const SPEND_CAPS_MICRO_USD = {
  anon: 5_000_000,
  ip: 25_000_000,
  global: 75_000_000,
} as const;

export const LIMIT_MESSAGES = {
  rateLimited: (s: number) => `You're moving fast! Give Co-learn about ${s} second${s === 1 ? "" : "s"} and try again.`,
  anonCap: "You've reached today's demo limit, thanks for trying Co-learn! It resets at midnight UTC.",
  ipCap: "Your network has reached today's demo limit, thanks for trying Co-learn! It resets at midnight UTC.",
  globalCap: "Co-learn has reached its demo budget for today, thanks for your interest! It resets at midnight UTC.",
  degraded: "Heads up: Co-learn's usage limits aren't working as expected right now. Please let the tool's owner know.",
} as const;

export interface LimitsStatus {
  degraded: boolean;
  lastIssueAt?: number;
  lastIssue?: "rate_limiter" | "spend_read" | "spend_write";
}

export interface LimitsDeps {
  store: Store;
  anonLimiter: RateLimiter;
  ipLimiter: RateLimiter;
  now?: () => number;
  log?: (line: string) => void;
}

export interface Limits {
  checkLimits(anonId: string, ip: string): Promise<LimitCheck>;
  recordUsage(anonId: string, ip: string, model: string, usage: UsageLike): Promise<void>;
  status(): LimitsStatus;
}

/** A degradation counts as current for this long after the last failure. */
const DEGRADED_WINDOW_MS = 10 * 60_000;

const scopesFor = (anonId: string, ip: string): UsageScope[] => [
  { kind: "anon", id: anonId },
  { kind: "ip", id: ip },
  { kind: "global" },
];

export function createLimits({ store, anonLimiter, ipLimiter, now = Date.now, log = (l) => console.error(l) }: LimitsDeps): Limits {
  let issue: { at: number; kind: NonNullable<LimitsStatus["lastIssue"]> } | null = null;
  const flag = (kind: NonNullable<LimitsStatus["lastIssue"]>) => { issue = { at: now(), kind }; };
  const status = (): LimitsStatus =>
    issue && now() - issue.at < DEGRADED_WINDOW_MS
      ? { degraded: true, lastIssueAt: issue.at, lastIssue: issue.kind }
      : { degraded: false };
  const allow = (): LimitCheck => (status().degraded ? { ok: true, warning: LIMIT_MESSAGES.degraded } : { ok: true });

  const tryLimit = async (limiter: RateLimiter, key: string) => {
    try {
      return await limiter.limit(key);
    } catch (e) {
      log(`[limits] rate limiter unavailable, allowing request (${redactError(e)})`);
      flag("rate_limiter");
      return { success: true, reset: 0 };
    }
  };

  return {
    async checkLimits(anonId, ip) {
      const [byAnon, byIp] = await Promise.all([tryLimit(anonLimiter, anonId), tryLimit(ipLimiter, ip)]);
      const blocked = [byAnon, byIp].filter((r) => !r.success);
      if (blocked.length > 0) {
        const retryAfterS = Math.max(1, Math.ceil((Math.max(...blocked.map((r) => r.reset)) - now()) / 1000));
        return { ok: false, code: "rate_limited", message: LIMIT_MESSAGES.rateLimited(retryAfterS), retryAfterS };
      }

      let spent: number[];
      try {
        spent = await store.getUsage(scopesFor(anonId, ip));
      } catch (e) {
        log(`[limits] spend caps unavailable, allowing request (${redactError(e)})`);
        flag("spend_read");
        return allow();
      }
      const [anon, byIpSpend, global] = spent;
      if (anon >= SPEND_CAPS_MICRO_USD.anon) return { ok: false, code: "spend_cap", message: LIMIT_MESSAGES.anonCap };
      if (byIpSpend >= SPEND_CAPS_MICRO_USD.ip) return { ok: false, code: "spend_cap", message: LIMIT_MESSAGES.ipCap };
      if (global >= SPEND_CAPS_MICRO_USD.global) return { ok: false, code: "spend_cap", message: LIMIT_MESSAGES.globalCap };
      return allow();
    },

    async recordUsage(anonId, ip, model, usage) {
      const cost = estimateCostMicroUsd(model, usage);
      if (cost <= 0) return;
      try {
        await store.addUsage(scopesFor(anonId, ip), cost);
      } catch (e) {
        log(`[limits] failed to record ${cost} micro-USD of usage (${redactError(e)})`);
        flag("spend_write");
      }
    },

    status,
  };
}

const globalForLimits = globalThis as unknown as { __colearnLimits?: Limits };

function defaultLimits(): Limits {
  if (!globalForLimits.__colearnLimits) {
    const creds = storeKind() === "redis" ? upstashCredentials() : null;
    const limiter = (kind: keyof typeof RATE_LIMITS): RateLimiter => {
      const { max, windowS } = RATE_LIMITS[kind];
      return creds ? upstashRateLimiter(creds, max, windowS, `ratelimit:${kind}`) : new MemoryRateLimiter(max, windowS * 1000);
    };
    globalForLimits.__colearnLimits = createLimits({ store: getStore(), anonLimiter: limiter("anon"), ipLimiter: limiter("ip") });
  }
  return globalForLimits.__colearnLimits;
}

/** Call before every Claude-backed request; on `ok: false` respond with `limitResponse(check)` (lib/platform/http.ts). */
export async function checkLimits(anonId: string, ip: string): Promise<LimitCheck> {
  return defaultLimits().checkLimits(anonId, ip);
}

/** Current health of the limits machinery (for /api/health and UI banners). */
export function limitsStatus(): LimitsStatus {
  return defaultLimits().status();
}

/** Call after every Claude response with its usage, to accumulate spend. Never throws. */
export async function recordUsage(anonId: string, ip: string, model: string, usage: Anthropic.Usage | Anthropic.Beta.BetaUsage): Promise<void> {
  return defaultLimits().recordUsage(anonId, ip, model, usage);
}
/** Small response helpers shared by route handlers. Error bodies are `{ error: string, code?: string }`. */
import { isStoreError, redactError, STORE_ERROR_MESSAGE } from "@/lib/store/errors";
import type { LimitCheck } from "./limits";

export function jsonError(status: number, error: string, code?: string, headers?: HeadersInit): Response {
  return Response.json(code ? { error, code } : { error }, { status, headers });
}

export const unauthorized = () => jsonError(401, "Type /co-learn to switch on Co-learn mode.", "no_session");
export const notFound = () => jsonError(404, "Not found.", "not_found");

/** 429 for a failed `checkLimits`, with Retry-After when known. */
export function limitResponse(check: Extract<LimitCheck, { ok: false }>): Response {
  const headers = check.retryAfterS ? { "Retry-After": String(check.retryAfterS) } : undefined;
  return jsonError(429, check.message, check.code, headers);
}

/** Maps StoreError to a friendly 503; anything else becomes a logged, generic 500. */
export function routeErrorResponse(e: unknown, route: string): Response {
  if (isStoreError(e)) return jsonError(503, STORE_ERROR_MESSAGE, "store_unavailable");
  console.error(`[${route}] unexpected error (${redactError(e)})`);
  return jsonError(500, "Something went wrong on our side. Please try again.", "internal");
}
/** Route-handler plumbing shared by Track D routes: identity, limits, metering, background work, errors. */
import Anthropic from "@anthropic-ai/sdk";
import { unstable_rethrow } from "next/navigation";
import { after } from "next/server";
import type { z } from "zod";
import { ContentRefusalError, ContentShapeError, ContentTruncatedError } from "@/lib/claude/content/errors";
import { withUsageReporter, type UsageReporter } from "@/lib/claude/content/usage";
import { clientIp, readAnonId } from "@/lib/platform/anon";
import { checkLimits, recordUsage } from "@/lib/platform/limits";
import { HttpError, type BackgroundTask, type LearningDeps } from "./deps";

export interface Caller {
  anonId: string;
  ip: string;
}

type ErrorBody = { error: string; code?: string; retryable?: boolean };
const errorJson = (status: number, body: ErrorBody) => Response.json(body, { status });

/** Identifies the caller from the anon cookie; throws 401 if it's missing. */
export async function requireCaller(request: Request): Promise<Caller> {
  const anonId = await readAnonId();
  if (!anonId) throw new HttpError(401, "Type /co-learn to start a session first.");
  return { anonId, ip: clientIp(request) };
}

export async function readBody<S extends z.ZodType>(request: Request, schema: S): Promise<z.infer<S>> {
  const raw: unknown = await request.json().catch(() => undefined);
  const parsed = schema.safeParse(raw);
  if (!parsed.success) throw new HttpError(400, parsed.error.issues[0]?.message ?? "Invalid request");
  return parsed.data;
}

/** Rate-limit and spend-cap check before any Claude-backed work. Returns a response to send if blocked. */
export async function limitBlock(caller: Caller): Promise<Response | null> {
  const check = await checkLimits(caller.anonId, caller.ip);
  if (check.ok) return null;
  return errorJson(429, { error: check.message, code: check.code, retryable: check.code === "rate_limited" });
}

export const meter = (caller: Caller): UsageReporter => (model, usage) => recordUsage(caller.anonId, caller.ip, model, usage);

export function metered<T>(caller: Caller, fn: () => Promise<T>): Promise<T> {
  return withUsageReporter(meter(caller), fn);
}

/** Runs background tasks after the response is sent, metered, with failures logged rather than thrown. */
export function schedule(deps: LearningDeps, caller: Caller, sessionId: string, tasks: BackgroundTask[]): void {
  if (!tasks.length) return;
  after(() =>
    metered(caller, async () => {
      for (const task of tasks) {
        try {
          await task();
        } catch (err) {
          await deps.store
            .logEvent({ at: deps.now(), anonId: caller.anonId, sessionId, name: "error", props: { where: "background", message: describe(err) } })
            .catch(() => undefined);
        }
      }
    }),
  );
}

function describe(err: unknown): string {
  return (err instanceof Error ? `${err.name}: ${err.message}` : String(err)).slice(0, 200);
}

/** Maps thrown errors to JSON responses, most specific first. Call from a route's catch block. */
export function errorResponse(err: unknown): Response {
  // Framework control flow (e.g. cookies() during prerender) must propagate to Next.js.
  unstable_rethrow(err);
  if (err instanceof HttpError) return errorJson(err.status, { error: err.message });
  if (err instanceof ContentRefusalError) return errorJson(422, { error: "Claude couldn't help with that one. Try rephrasing or skip it.", code: "refusal" });
  if (err instanceof ContentTruncatedError || err instanceof ContentShapeError) return errorJson(502, { error: "That didn't come out right. Please try again.", code: "upstream", retryable: true });
  if (err instanceof Anthropic.RateLimitError) return errorJson(503, { error: "Claude is busy right now. Please try again in a moment.", code: "upstream", retryable: true });
  if (err instanceof Anthropic.BadRequestError) {
    console.error("[colearn] Claude bad request:", describe(err));
    return errorJson(502, { error: "Something went wrong talking to Claude.", code: "bad_request" });
  }
  if (err instanceof Anthropic.APIError) return errorJson(502, { error: "Claude is unavailable right now. Please try again.", code: "upstream", retryable: true });
  console.error("[colearn] unexpected error:", describe(err));
  return errorJson(500, { error: "Something went wrong." });
}
/** Sliding-window rate limiters: Upstash-backed in production, in-memory for local dev and tests. */
import { Ratelimit } from "@upstash/ratelimit";
import { Redis } from "@upstash/redis";
import type { UpstashCredentials } from "@/lib/store/redis-kv";

export interface RateLimitResult {
  success: boolean;
  /** Epoch ms when the caller may retry. */
  reset: number;
}

export interface RateLimiter {
  limit(key: string): Promise<RateLimitResult>;
}

/** Exact sliding log. Per process only, which is fine for local dev and a single test runner. */
export class MemoryRateLimiter implements RateLimiter {
  private hits = new Map<string, number[]>();

  constructor(
    private readonly max: number,
    private readonly windowMs: number,
    private readonly now: () => number = Date.now,
  ) {}

  async limit(key: string): Promise<RateLimitResult> {
    const now = this.now();
    const recent = (this.hits.get(key) ?? []).filter((t) => t > now - this.windowMs);
    if (recent.length >= this.max) {
      this.hits.set(key, recent);
      return { success: false, reset: recent[0] + this.windowMs };
    }
    recent.push(now);
    this.hits.set(key, recent);
    return { success: true, reset: recent[0] + this.windowMs };
  }
}

export function upstashRateLimiter(creds: UpstashCredentials, max: number, windowS: number, prefix: string): RateLimiter {
  const limiter = new Ratelimit({
    // A separate client with Upstash's default (de)serialization, which the ratelimit scripts expect.
    redis: new Redis(creds),
    limiter: Ratelimit.slidingWindow(max, `${windowS} s`),
    prefix,
    analytics: false,
    timeout: 2000, // Upstash allows the request through if Redis is slower than this
  });
  return {
    async limit(key) {
      const r = await limiter.limit(key);
      return { success: r.success, reset: r.reset };
    },
  };
}

