  /** Files API id of the demo churn CSV (env DEMO_FILE_ID). */
  demoFileId?: string;
}

export function defaultDeps(): WorkDeps {
  return {
    store: getStore(),
    engine,
    content,
    startStream: (params, signal) => anthropic().beta.messages.stream(params, { signal }),
    checkLimits,
    recordUsage,
    now: Date.now,
    newId: () => crypto.randomUUID(),
    demoFileId: process.env.DEMO_FILE_ID || undefined,
  };
}
/**
 * Mutable state for one work turn, plus race-safe persistence.
 *
 * History is append-only (preserved thinking): messages are only ever appended, never edited once sent.
 * New messages are "pending" until a model response for them succeeds ("committed"), so a failed first
 * request never leaves a dangling user + system pair in stored history.
 */
import type Anthropic from "@anthropic-ai/sdk";
import type { ApiMessages, Session, TranscriptItem } from "@/lib/contracts/session";
import type { Store } from "@/lib/contracts/store";
import { codeResult, fileIdsFromContent, transcriptFromContent } from "./blocks";

export type ApiMessage = Anthropic.Beta.BetaMessageParam;

/** Session fields the work loop owns; everything else may be patched concurrently by other routes. */
export type OwnedSessionFields = Pick<Session, "engine" | "containerId" | "fileIds" | "demoFileAttached">;

export class TurnState {
  private pending: ApiMessage[] = [];
  private committed = 0;
  private items = new Map<string, TranscriptItem>();
  private staged: TranscriptItem[] = [];
  private onCommit: (() => void)[] = [];
  dirty = false;
  readonly store: Store;
  readonly session: Session;
  private readonly history: ApiMessage[];

  constructor(store: Store, session: Session, history: ApiMessage[]) {
    this.store = store;
    this.session = session;
    this.history = history;
  }

  /** Full message list for the next request. */
  messages(): ApiMessage[] {
    return [...this.history, ...this.pending];
  }

  lastStoredMessage(): ApiMessage | undefined {
    return this.history.at(-1);
  }

  push(message: ApiMessage): void {
    this.pending.push(message);
  }

  /** Transcript item that only becomes visible once the turn's first request succeeds. */
  stage(item: TranscriptItem): void {
    this.staged.push(item);
  }

  /** Runs once, at the first commit (e.g. mark the demo file attached). */
  whenCommitted(fn: () => void): void {
    this.onCommit.push(fn);
  }

  /** Last uncommitted user message (still safe to amend: the API has never accepted it). */
  uncommittedUserMessage(): ApiMessage | undefined {
    return this.pending.slice(this.committed).findLast((m) => m.role === "user");
  }

  commit(): void {
    this.committed = this.pending.length;
    if (this.staged.length) {
      // Staged items (the user's message) come before anything the response produced.
      this.items = new Map([...this.staged.splice(0).map((i) => [i.id, i] as const), ...this.items]);
    }
    for (const fn of this.onCommit.splice(0)) fn();
    this.dirty = true;
  }

  /** Appends an assistant response exactly as returned, plus its transcript items and output files. */
  appendAssistant(message: Anthropic.Beta.BetaMessage): void {
    // An empty assistant turn would be rejected on the next request; it carries nothing to preserve.
    const content: Anthropic.Beta.BetaContentBlockParam[] = message.content.length ? message.content : [{ type: "text", text: "…" }];
    this.push({ role: "assistant", content });
    for (const item of transcriptFromContent(message.id, message.content)) this.upsert(item);
    // A code result can land in a later message than its tool call (e.g. across pause_turn).
    for (const block of message.content) {
      const result = codeResult(block);
      const run = result && this.items.get(result.toolUseId);
      if (result && run?.kind === "code_run" && run.returnCode === undefined) {
        this.upsert({ ...run, stdout: result.stdout, stderr: result.stderr, returnCode: result.returnCode, fileIds: result.fileIds });
      }
    }
    const files = fileIdsFromContent(message.content);
    if (files.length) this.session.fileIds = [...new Set([...this.session.fileIds, ...files])];
  }

  addItem(item: TranscriptItem): void {
    this.upsert(item);
    this.dirty = true;
  }

  markDirty(): void {
    this.dirty = true;
  }

  private upsert(item: TranscriptItem): void {
    this.items.set(item.id, item);
  }

  /** Writes owned session fields onto the latest stored session, committed history, and new transcript items. */
  async persist(): Promise<void> {
    const { store, session } = this;
    const latest = (await store.getSession(session.id)) ?? session;
    const owned: OwnedSessionFields = {
      engine: session.engine,
      containerId: session.containerId,
      fileIds: [...new Set([...latest.fileIds, ...session.fileIds])],
      demoFileAttached: latest.demoFileAttached || session.demoFileAttached,
    };
    await store.putSession({ ...latest, ...owned });
    // ApiMessages is typed with the non-beta MessageParam; beta blocks (e.g. `fallback`) are wire-compatible.
    await store.putApiMessages(session.id, [...this.history, ...this.pending.slice(0, this.committed)] as unknown as ApiMessages);
    if (this.items.size) {
      const transcript = await store.getTranscript(session.id);
      const index = new Map(transcript.map((t, i) => [t.id, i]));
      for (const item of this.items.values()) {
        const at = index.get(item.id);
        if (at === undefined) transcript.push(item);
        else transcript[at] = item;
      }
      await store.putTranscript(session.id, transcript);
    }
    this.dirty = false;
  }
}
/**
 * Server-built user-turn text for non-message requests (never trusts client text; design-plan §5.3).
 */
import type { BossState, MomentRecord } from "@/lib/contracts/session";

const CONTINUE = "Continue the work, building on their choice.";

const label = (m: MomentRecord) => `moment ${m.id} (${m.type} · ${m.candidate.concept})`;

function answerText(m: MomentRecord): string {
  if (m.answer?.trim()) return `"${m.answer.trim()}"`;
  if (m.mcChoice !== undefined) {
    const option = m.candidate.mc_fallback.options[m.mcChoice];
    return `"${option ?? `option ${m.mcChoice + 1}`}" (picked from multiple-choice options)`;
  }
  return "(no answer text)";
}

/** Text for a `moment_response` request, or null if the moment isn't in a state that can continue the work. */
export function momentResponseText(m: MomentRecord): string | null {
  switch (m.status) {
    case "answered": {
      const verdict = m.verdict ? ` Grade: ${m.verdict}.` : "";
      const why = m.why ? ` Why: ${m.why}` : "";
      return `[Learner response to ${label(m)}] Their answer: ${answerText(m)}.${verdict}${why}\n${CONTINUE}`;
    }
    case "awaiting_prediction_result":
      return `[Learner response to ${label(m)}] The learner predicted: ${answerText(m)}. Now run the code, then call resolve_prediction with moment_id="${m.id}".\n${CONTINUE}`;
    case "skipped":
      return `[Learner skipped ${label(m)}] Make the call yourself and briefly say why.\n${CONTINUE}`;
    case "deferred":
      return `[Learner deferred ${label(m)} to the end-of-session quiz] Make the call yourself and briefly say why.\n${CONTINUE}`;
    case "reported":
      return `[Learner reported ${label(m)} as unclear or wrong] Make the call yourself and briefly say why.\n${CONTINUE}`;
    case "awaiting_answer":
      return null;
  }
}

export function bossResultText(boss: BossState, concepts: string[]): string | null {
  if (!boss.outcome) return null;
  const outcome = {
    flawless: "a flawless victory",
    victory: "a victory",
    retreat: "the boss retreated (the learner missed more than half; those concepts go to review)",
  }[boss.outcome];
  const about = concepts.length ? ` It covered: ${concepts.join(", ")}.` : "";
  return `[Boss challenge "${boss.name}" finished: ${outcome}.]${about} Acknowledge it in one short line, then continue the work.`;
}

export function skippedPendingNote(m: Pick<MomentRecord, "id" | "type" | "candidate">): string {
  return `[The learner skipped the open learning moment ${m.id} (${m.type} · ${m.candidate.concept}) and wrote a new message instead. Make that call yourself if it still matters.]`;
}

export const CONTINUE_TEXT = "Please continue the work where you left off.";

export const CONTAINER_RESET_NOTE =
  "[Note from the app: the coding environment was reset, so earlier files and variables are gone. Reload the data from the uploaded files (or regenerate it) before continuing.]";

content.content:
/**
 * The work turn (design-plan §5): a manual streaming tool loop on the native SDK.
 * Code execution runs server-side; our function tools run here. A shown learning moment or a due boss ends
 * the turn; skipped moments return a tool_result and the loop keeps going within the same turn.
 */
import type Anthropic from "@anthropic-ai/sdk";
import { MODELS } from "@/lib/claude/models";
import type { TurnEndReason } from "@/lib/contracts/stream";
import type { ModelParams, WorkDeps } from "./deps";
import { demoDataNote, renderContext } from "./context";
import { describeError, isAbort, isContainerError, REFUSAL_ERROR, toErrorEvent } from "./errors";
import { handleTool, ToolContext, type PauseReason, type ToolOutcome } from "./handlers";
import type { TurnPlan } from "./prepare";
import { WORK_SYSTEM } from "./prompt";
import { TurnState, type ApiMessage } from "./state";
import { consumeStream, type Emit } from "./stream";
import { WORK_TOOLS } from "./tools";
import { CONTAINER_RESET_NOTE, skippedPendingNote } from "./userText";

/** Model requests per user turn (pause_turn re-sends included). */
export const MAX_STEPS = 8;

const CUT_OFF_TOOL_RESULT = "Your response hit the output limit, so this tool call was cut off and not run. Call it again with a shorter input.";

export function buildParams(messages: ApiMessage[], containerId: string | undefined): ModelParams {
  const route = MODELS.work;
  return {
    model: route.model,
    max_tokens: route.maxTokens,
    output_config: { effort: route.effort },
    system: WORK_SYSTEM,
    tools: WORK_TOOLS,
    messages,
    // Top-level breakpoint: caches the growing conversation prefix across loop steps and turns.
    cache_control: { type: "ephemeral" },
    ...(containerId ? { container: containerId } : {}),
    betas: ["server-side-fallback-2026-07-01"],
    fallbacks: "default",
  };
}

export async function runTurn(deps: WorkDeps, plan: TurnPlan, emit: Emit, signal: AbortSignal): Promise<void> {
  const { store } = deps;
  const { anonId, ip, session, user } = plan;
  emit({ type: "status", status: "thinking" });

  const limits = await deps.checkLimits(anonId, ip);
  if (!limits.ok) {
    emit({ type: "error", message: limits.message, retryable: limits.code === "rate_limited", code: limits.code });
    emit({ type: "turn_end", reason: "error", detail: limits.code });
    return;
  }

  const history = (await store.getApiMessages(session.id)) as unknown as ApiMessage[];
  const state = new TurnState(store, session, history);
  const ctx = new ToolContext(deps, state, user);

  const flush = () => {
    for (const event of ctx.outbox.splice(0)) emit(event);
  };
  const end = async (reason: TurnEndReason) => {
    // Persist before the browser hears about a moment or boss: the grade/boss routes read this state next.
    await state.persist();
    flush();
    emit({ type: "turn_end", reason });
  };

  try {
    const prefix = await settlePendingMoment(ctx, plan);
    session.engine = deps.engine.recordWorkTurn(session.engine);
    state.markDirty();
    if (plan.modelText !== null) await addUserTurn(ctx, plan, prefix);

    let resetTried = false;
    for (let step = 0; ; ) {
      if (step >= MAX_STEPS) return await end("max_steps");
      step++;

      let started = false;
      let message: Anthropic.Beta.BetaMessage;
      try {
        const stream = deps.startStream(buildParams(state.messages(), session.containerId), signal);
        message = await consumeStream(stream, emit, () => (started = true));
      } catch (err) {
        if (started || resetTried || !session.containerId || !isContainerError(err)) throw err;
        resetTried = true;
        step--;
        resetContainer(ctx);
        emit({ type: "notice", itemId: `notice:${deps.newId()}`, text: "The coding environment was reset; reloading data." });
        continue;
      }

      await deps.recordUsage(anonId, ip, message.model, message.usage);
      if (message.container?.id) session.containerId = message.container.id;

      if (message.stop_reason === "refusal") {
        // Nothing from a refused response is kept; earlier committed steps stay.
        emit(REFUSAL_ERROR);
        return await end("refusal");
      }

      state.appendAssistant(message);
      if (message.stop_reason === "pause_turn") {
        state.commit();
        continue;
      }

      const toolUses = message.content.filter((b): b is Anthropic.Beta.BetaToolUseBlock => b.type === "tool_use");
      if (toolUses.length === 0) {
        state.commit();
        return await end("end_turn");
      }

      const pause = await runTools(ctx, toolUses, message.stop_reason === "max_tokens");
      state.commit();
      if (pause) return await end(pause);
      flush();
    }
  } catch (err) {
    if (signal.aborted || isAbort(err)) return;
    console.error("work turn failed:", describeError(err));
    await ctx.log("error", { where: "chat", error: describeError(err).slice(0, 200) }).catch(() => {});
    // Save committed progress before the client can retry.
    await persistQuietly(state);
    emit(toErrorEvent(err));
    emit({ type: "turn_end", reason: "error" });
  } finally {
    await persistQuietly(state);
  }
}

async function persistQuietly(state: TurnState): Promise<void> {
  if (!state.dirty) return;
  await state.persist().catch((e) => console.error("persist failed:", describeError(e)));
}

/** Runs every tool call of one response and appends all results in a single user message. */
async function runTools(ctx: ToolContext, toolUses: Anthropic.Beta.BetaToolUseBlock[], cutOff: boolean): Promise<PauseReason | undefined> {
  let pause: PauseReason | undefined;
  const results: Anthropic.Beta.BetaToolResultBlockParam[] = [];
  for (const block of toolUses) {
    const outcome: ToolOutcome = cutOff ? { content: CUT_OFF_TOOL_RESULT, isError: true } : await handleTool(ctx, block);
    results.push({ type: "tool_result", tool_use_id: block.id, content: outcome.content, ...(outcome.isError ? { is_error: true } : {}) });
    pause ??= outcome.pause;
  }
  ctx.state.push({ role: "user", content: results });
  return pause;
}

/** Clears a pending moment the learner moved past; returns a note for Claude if it was skipped. */
async function settlePendingMoment(ctx: ToolContext, plan: TurnPlan): Promise<string | null> {
  const { session } = ctx.state;
  const pendingId = session.engine.pendingMomentId;
  if (!pendingId) return null;
  session.engine = { ...session.engine, pendingMomentId: undefined };
  ctx.state.markDirty();
  if (plan.request.kind === "moment_response" && plan.request.momentId === pendingId) return null;

  const moment = await ctx.deps.store.getMoment(session.id, pendingId);
  if (moment?.status !== "awaiting_answer") return null;
  await ctx.deps.store.putMoment({ ...moment, status: "skipped" });
  await ctx.log("moment_skipped", { momentId: moment.id, via: plan.request.kind });
  return skippedPendingNote(moment);
}

async function addUserTurn(ctx: ToolContext, plan: TurnPlan, prefix: string | null): Promise<void> {
  const { deps, state } = ctx;
  const { session } = state;
  const now = deps.now();
  const text = prefix ? `${prefix}\n\n${plan.modelText}` : plan.modelText!;
  const content: Anthropic.Beta.BetaContentBlockParam[] = [{ type: "text", text }];
  const notes: string[] = [];

  if (session.intent.demo && !session.demoFileAttached) {
    if (deps.demoFileId) content.push({ type: "container_upload", file_id: deps.demoFileId });
    notes.push(demoDataNote(!!deps.demoFileId));
    state.whenCommitted(() => (session.demoFileAttached = true));
  }
  state.push({ role: "user", content });
  if (plan.userText !== undefined) state.stage({ kind: "user", id: `user:${deps.newId()}`, text: plan.userText, at: now });

  const summary = deps.engine.summarize(await ctx.gateContext(now));
  state.push({ role: "system", content: renderContext({ session, summary, now, notes }) });
}

/** Drops an expired container and tells Claude (in the not-yet-accepted user turn) to reload its data. */
function resetContainer(ctx: ToolContext): void {
  const { deps, state } = ctx;
  const { session } = state;
  session.containerId = undefined;
  const message = state.uncommittedUserMessage();
  if (!message || typeof message.content === "string") return;
  message.content.push({ type: "text", text: CONTAINER_RESET_NOTE });
  const hasUpload = message.content.some((b) => b.type === "container_upload");
  if (session.intent.demo && deps.demoFileId && !hasUpload) {
    message.content.push({ type: "container_upload", file_id: deps.demoFileId });
  }
}
/**
 * Handlers for our function tools (design-plan §5.2). Each returns the tool_result content and, when the
 * turn must pause, the reason. Browser events go to the outbox, which the loop flushes after persisting.
 */
import type Anthropic from "@anthropic-ai/sdk";
import type { z } from "zod";
import {
  LearningMomentInputSchema,
  MilestoneInputSchema,
  ResolvePredictionInputSchema,
  type LearningMomentInput,
  type Verdict,
} from "@/lib/contracts/moment";
import type { GateContext, GateDecision, MasteryMap } from "@/lib/contracts/engine";
import type { AppEvent, MomentRecord, User } from "@/lib/contracts/session";
import type { ChatStreamEvent, XpAward } from "@/lib/contracts/stream";
import { toMomentView } from "@/lib/views";
import type { WorkDeps } from "./deps";
import { sessionEndsAt } from "./context";
import type { TurnState } from "./state";
import { LEARNING_MOMENT, MILESTONE_REACHED, RESOLVE_PREDICTION } from "./tools";

export type PauseReason = "awaiting_learner" | "boss_due";

export interface ToolOutcome {
  content: string;
  isError?: boolean;
  pause?: PauseReason;
}

export class ToolContext {
  readonly outbox: ChatStreamEvent[] = [];
  private mastery?: MasteryMap;
  readonly deps: WorkDeps;
  readonly state: TurnState;
  readonly user: User;

  constructor(deps: WorkDeps, state: TurnState, user: User) {
    this.deps = deps;
    this.state = state;
    this.user = user;
  }

  get anonId() {
    return this.state.session.anonId;
  }

  async gateContext(now: number): Promise<GateContext> {
    this.mastery ??= await this.deps.store.getMastery(this.anonId);
    return {
      state: this.state.session.engine,
      mastery: this.mastery,
      settings: this.user.settings,
      familiarity: this.state.session.intent.familiarity,
      now,
    };
  }

  log(name: AppEvent["name"], props?: AppEvent["props"]): Promise<void> {
    return this.deps.store.logEvent({ at: this.deps.now(), anonId: this.anonId, sessionId: this.state.session.id, name, props });
  }
}

const json = (value: unknown) => JSON.stringify(value);

function invalid(error: z.ZodError): ToolOutcome {
  const issues = error.issues.slice(0, 5).map((i) => `${i.path.join(".") || "input"}: ${i.message}`);
  return { content: `Invalid input. Fix these and call the tool again: ${issues.join("; ")}`, isError: true };
}

export async function handleTool(ctx: ToolContext, block: Anthropic.Beta.BetaToolUseBlock): Promise<ToolOutcome> {
  switch (block.name) {
    case LEARNING_MOMENT:
      return learningMoment(ctx, block);
    case RESOLVE_PREDICTION:
      return resolvePrediction(ctx, block);
    case MILESTONE_REACHED:
      return milestone(ctx, block);
    default:
      return { content: `Unknown tool: ${block.name}`, isError: true };
  }
}

async function verified(ctx: ToolContext, candidate: LearningMomentInput): Promise<boolean> {
  try {
    return (await ctx.deps.content.verifyMoment({ candidate })).ok;
  } catch (err) {
    // Fail closed (P9): an unverifiable moment is skipped and the work simply continues.
    console.error("verifyMoment failed", err instanceof Error ? err.message : err);
    return false;
  }
}

async function learningMoment(ctx: ToolContext, block: Anthropic.Beta.BetaToolUseBlock): Promise<ToolOutcome> {
  const parsed = LearningMomentInputSchema.safeParse(block.input);
  if (!parsed.success) return invalid(parsed.error);
  const candidate = parsed.data;
  const { deps, state } = ctx;
  const now = deps.now();
  const moment: MomentRecord = {
    id: deps.newId(),
    sessionId: state.session.id,
    createdAt: now,
    type: candidate.type,
    candidate,
    toolUseId: block.id,
    status: "awaiting_answer",
    mcOffered: false,
  };

  await ctx.log("moment_proposed", { momentId: moment.id, type: candidate.type, concept: candidate.concept, value: candidate.learning_value, difficulty: candidate.difficulty });
  let decision: GateDecision = deps.engine.gate(candidate, await ctx.gateContext(now));
  if (decision.action === "show" && !(await verified(ctx, candidate))) decision = { action: "skip", reason: "unverified" };
  await ctx.log("moment_gated", { momentId: moment.id, action: decision.action, reason: decision.action === "show" ? null : decision.reason });

  if (decision.action === "defer") {
    await deps.store.putMoment({ ...moment, status: "deferred" });
    await ctx.log("moment_deferred", { momentId: moment.id });
    return { content: json({ status: "skip", reason: decision.reason }) };
  }
  if (decision.action === "skip") return { content: json({ status: "skip", reason: decision.reason }) };

  await deps.store.putMoment(moment);
  state.session.engine = deps.engine.recordShown(state.session.engine, moment.id, now);
  const itemId = `moment:${moment.id}`;
  state.addItem({ kind: "moment", id: itemId, momentId: moment.id });
  ctx.outbox.push({ type: "moment", itemId, moment: toMomentView(moment) });
  await ctx.log("moment_shown", { momentId: moment.id, type: candidate.type, concept: candidate.concept });
  return { content: json({ status: "awaiting_learner", moment_id: moment.id }), pause: "awaiting_learner" };
}

const SCORE: Record<Verdict, number> = { correct: 1, partial: 0.5, incorrect: 0 };

/** Adds XP to the stored user (re-read to avoid clobbering concurrent updates) and returns the award. */
export async function awardXp(ctx: ToolContext, amount: number, reason: string): Promise<XpAward> {
  const { store, engine } = ctx.deps;
  const user = (await store.getUser(ctx.anonId)) ?? ctx.user;
  const before = engine.levelFor(user.xp);
  user.xp += amount;
  const after = engine.levelFor(user.xp);
  user.level = after.level;
  const award: XpAward = { amount, reason, level: after };
  if (after.level > before.level) {
    const rewards = engine.rewardsBetween(before.level, after.level);
    for (const r of rewards) {
      const list = r.kind === "theme" ? user.unlocks.themes : user.unlocks.soundPacks;
      if (!list.includes(r.id)) list.push(r.id);
    }
    award.levelUp = { from: before.level, to: after.level, rewards };
    await ctx.log("level_up", { from: before.level, to: after.level });
  }
  await store.putUser(user);
  return award;
}

async function resolvePrediction(ctx: ToolContext, block: Anthropic.Beta.BetaToolUseBlock): Promise<ToolOutcome> {
  const parsed = ResolvePredictionInputSchema.safeParse(block.input);
  if (!parsed.success) return invalid(parsed.error);
  const input = parsed.data;
  const { deps, state } = ctx;
  const moment = await deps.store.getMoment(state.session.id, input.moment_id);
  if (!moment || moment.status !== "awaiting_prediction_result") {
    return { content: `No prediction is waiting for a result with moment_id "${input.moment_id}". Don't call resolve_prediction for it again.`, isError: true };
  }
  const now = deps.now();
  const xp = deps.engine.xpFor({ kind: "prediction", verdict: input.verdict });
  const award = await awardXp(ctx, xp, `Prediction: ${input.verdict}`);
  await deps.store.putMoment({ ...moment, status: "answered", verdict: input.verdict, why: input.why, xp, answeredAt: now });

  const concept = moment.candidate.concept;
  const score = SCORE[input.verdict];
  const gate = await ctx.gateContext(now);
  const mastery = deps.engine.updateMastery(gate.mastery[concept], score, moment.candidate.difficulty, state.session.intent.familiarity, now);
  gate.mastery[concept] = mastery;
  await deps.store.putMastery(ctx.anonId, concept, mastery);
  state.session.engine = deps.engine.recordOutcome(state.session.engine, { momentId: moment.id, concept, type: moment.type, score, at: now });
  await ctx.log("moment_answered", { momentId: moment.id, type: moment.type, concept, verdict: input.verdict, xp });

  const itemId = `prediction:${moment.id}`;
  state.addItem({ kind: "prediction_reveal", id: itemId, momentId: moment.id, actualResult: input.actual_result, verdict: input.verdict, why: input.why, xp });
  ctx.outbox.push({ type: "prediction_reveal", itemId, momentId: moment.id, actualResult: input.actual_result, verdict: input.verdict, why: input.why, xp: award });
  return { content: "recorded" };
}

export const BOSS_INSTRUCTION =
  "Stop here and wait: a short boss challenge starts now. Don't continue the work until its result arrives.";

async function milestone(ctx: ToolContext, block: Anthropic.Beta.BetaToolUseBlock): Promise<ToolOutcome> {
  const parsed = MilestoneInputSchema.safeParse(block.input);
  if (!parsed.success) return invalid(parsed.error);
  const { deps, state } = ctx;
  const engineState = state.session.engine;
  // A moment shown in the same response takes priority; the boss can come at a later milestone.
  const bossDue = !engineState.pendingMomentId && deps.engine.bossDue(engineState, deps.now(), sessionEndsAt(state.session));
  state.addItem({ kind: "milestone", id: block.id, label: parsed.data.label });
  ctx.outbox.push({ type: "milestone", itemId: block.id, label: parsed.data.label, bossDue });
