  xp?: XpAward;
}

export const answerXpReason = (verdict: Verdict, afterMC: boolean) =>
  verdict === "correct" ? (afterMC ? "Correct with options" : "Correct answer") : verdict === "partial" ? "Partly right" : "Answer";

export async function resolveMoment(
  deps: LearningDeps,
  session: Session,
  record: MomentRecord,
  res: Resolution,
  xp: { events: XpEvent[]; reason: string },
): Promise<Resolved> {
  const now = deps.now();
  const score = scoreFor(res.verdict, res.afterMC);
  const { concept, difficulty } = record.candidate;

  const mastery = await deps.store.getMastery(session.anonId);
  const nextMastery = deps.engine.updateMastery(mastery[concept], score, difficulty, session.intent.familiarity, now);
  await deps.store.putMastery(session.anonId, concept, nextMastery);

  await patchSession(deps, session.id, (latest) => ({
    engine: deps.engine.recordOutcome(latest.engine, { momentId: record.id, concept, type: record.type, score, at: now }),
  }));

  const award = await awardXp(deps, session.anonId, session.id, xp.events, xp.reason);

  const moment: MomentRecord = {
    ...record,
    status: "answered",
    verdict: res.verdict,
    why: res.why,
    missingPoints: res.missingPoints,
    mcChoice: res.mcChoice ?? record.mcChoice,
    xp: award?.amount ?? 0,
    answeredAt: now,
  };
  await deps.store.putMoment(moment);
  await deps.store.logEvent({
    at: now,
    anonId: session.anonId,
    sessionId: session.id,
    name: "moment_answered",
    props: { momentId: record.id, type: record.type, concept, verdict: res.verdict, afterMC: res.afterMC, score, boss: !!record.bossId },
  });
  return { moment, score, xp: award };
}
/**
 * POST /api/moment/grade logic: free-form grading with MC fallback, deterministic MC grading,
 * skip/defer/report, and boss hits. See design-plan §5.3, §6.3, §7.4.
 */
import { z } from "zod";
import type { ChatRequest, GradeRequest, GradeResponse } from "@/lib/contracts/api";
import type { XpEvent } from "@/lib/contracts/engine";
import type { MomentRecord, Session } from "@/lib/contracts/session";
import { toMomentView } from "@/lib/views";
import { advanceBoss, mergeAwards } from "./boss";
import { HttpError, type BackgroundTask, type HandlerResult, type LearningDeps } from "./deps";
import { answerXpReason, resolveMoment, type Resolution } from "./resolve";
import { hitFor, isSettled } from "./scores";
import { loadOwnedSession, patchSession } from "./sessionStore";

const ids = { sessionId: z.string().min(1).max(100), momentId: z.string().min(1).max(100) };
export const GradeRequestSchema = z.union([
  z.object({ ...ids, action: z.literal("submit"), answer: z.string().max(4000) }),
  z.object({ ...ids, action: z.literal("mc"), choice: z.number().int().min(0).max(3) }),
  z.object({ ...ids, action: z.literal("show_options") }),
  z.object({ ...ids, action: z.enum(["skip", "defer", "report"]) }),
]);

const answerable = (m: MomentRecord) => m.status === "awaiting_answer" || m.status === "deferred";

interface Ctx {
  deps: LearningDeps;
  session: Session;
  record: MomentRecord;
  /** Deferred moments answered during wrap-up never continue the work loop. */
  fromWrapUp: boolean;
}

export async function handleGrade(deps: LearningDeps, anonId: string, req: GradeRequest): Promise<HandlerResult<GradeResponse>> {
  const session = await loadOwnedSession(deps, anonId, req.sessionId);
  const record = await deps.store.getMoment(session.id, req.momentId);
  if (!record) throw new HttpError(404, "Moment not found");
  const ctx: Ctx = { deps, session, record, fromWrapUp: session.status === "wrapped" || record.status === "deferred" };

  if (req.action === "report") return settleWithoutGrade(ctx, "report");
  if (!answerable(record)) throw new HttpError(409, "This moment has already been answered or set aside");

  switch (req.action) {
    case "submit":
      return submit(ctx, req.answer);
    case "mc":
      return multipleChoice(ctx, req.choice);
    case "show_options":
      return showOptions(ctx);
    default:
      return settleWithoutGrade(ctx, req.action);
  }
}

const continueWork = (ctx: Ctx): ChatRequest | undefined =>
  ctx.fromWrapUp ? undefined : { sessionId: ctx.session.id, kind: "moment_response", momentId: ctx.record.id };

const done = (body: GradeResponse, background: BackgroundTask[] = []): HandlerResult<GradeResponse> => ({ body, background });

async function submit(ctx: Ctx, rawAnswer: string): Promise<HandlerResult<GradeResponse>> {
  const { deps, session, record } = ctx;
  const answer = rawAnswer.trim();
  if (!answer) throw new HttpError(400, "Answer is empty");

  // Predictions are graded against the real run by the work loop (resolve_prediction), not here.
  if (record.type === "predict" && !record.bossId && !ctx.fromWrapUp) {
    const pending: MomentRecord = { ...record, answer, status: "awaiting_prediction_result", answeredAt: deps.now() };
    await deps.store.putMoment(pending);
    await deps.store.logEvent({ at: deps.now(), anonId: session.anonId, sessionId: session.id, name: "moment_answered", props: { momentId: record.id, type: record.type, pendingPrediction: true } });
    return done({ moment: toMomentView(pending), offerMC: false, continueWith: continueWork(ctx) });
  }

  const grade = await deps.content.gradeAnswer({ candidate: record.candidate, answer });
  const answered: MomentRecord = { ...record, answer };

  if (grade.verdict === "incorrect" && !record.mcOffered) {
    const retry: MomentRecord = { ...answered, mcOffered: true, verdict: "incorrect", why: grade.why, missingPoints: grade.missingPoints };
    await deps.store.putMoment(retry);
    await deps.store.logEvent({ at: deps.now(), anonId: session.anonId, sessionId: session.id, name: "mc_offered", props: { momentId: record.id, after: "miss" } });
    return done({ moment: toMomentView(retry), verdict: "incorrect", offerMC: true });
  }

  return finalize({ ...ctx, record: answered }, { verdict: grade.verdict, why: grade.why, missingPoints: grade.missingPoints, afterMC: false });
}

async function multipleChoice(ctx: Ctx, choice: number): Promise<HandlerResult<GradeResponse>> {
  const { options, correct_index: ci, why } = ctx.record.candidate.mc_fallback;
  if (choice >= options.length) throw new HttpError(400, "Choice out of range");
  const correct = choice === ci;
  const explanation = correct ? why[ci] : `${why[choice]} The best answer is "${options[ci]}": ${why[ci]}`;
  return finalize(
    { ...ctx, record: { ...ctx.record, mcOffered: true } },
    { verdict: correct ? "correct" : "incorrect", why: explanation, afterMC: true, mcChoice: choice },
  );
}

async function showOptions(ctx: Ctx): Promise<HandlerResult<GradeResponse>> {
  const { deps, session, record } = ctx;
  const next: MomentRecord = { ...record, mcOffered: true };
  await deps.store.putMoment(next);
  await deps.store.logEvent({ at: deps.now(), anonId: session.anonId, sessionId: session.id, name: "mc_offered", props: { momentId: record.id, after: "requested" } });
  return done({ moment: toMomentView(next), offerMC: false });
}

/** Resolves the moment (mastery, engine, XP); boss moments also land a hit. */
async function finalize(ctx: Ctx, res: Resolution): Promise<HandlerResult<GradeResponse>> {
  const { deps, session, record } = ctx;

  if (!record.bossId) {
    const events: XpEvent[] = [{ kind: "answer", verdict: res.verdict, afterMC: res.afterMC }];
    const resolved = await resolveMoment(deps, session, record, res, { events, reason: answerXpReason(res.verdict, res.afterMC) });
    return done({ moment: toMomentView(resolved.moment), verdict: res.verdict, offerMC: false, xp: resolved.xp, continueWith: continueWork(ctx) });
  }

  const hit = hitFor(res.verdict, res.afterMC);
  const events: XpEvent[] = hit > 0 ? [{ kind: "boss_hit", partial: hit < 1 }] : [];
  const resolved = await resolveMoment(deps, session, record, res, { events, reason: hit >= 1 ? "Boss hit" : "Glancing boss hit" });
  const advance = await advanceBoss(deps, session, record.bossId, hit);
  return done(
    {
      moment: toMomentView(resolved.moment),
      verdict: res.verdict,
      offerMC: false,
      xp: mergeAwards(resolved.xp, advance?.xp),
      boss: advance?.boss,
      continueWith: advance?.finished ? { sessionId: session.id, kind: "boss_result", bossId: record.bossId } : undefined,
    },
    advance?.background,
  );
}

const STATUS = { skip: "skipped", defer: "deferred", report: "reported" } as const;
const EVENT = { skip: "moment_skipped", defer: "moment_deferred", report: "moment_reported" } as const;

/** Skip, defer, or report: no mastery or XP. Boss questions can't be deferred, so defer counts as a skip there. */
async function settleWithoutGrade(ctx: Ctx, action: "skip" | "defer" | "report"): Promise<HandlerResult<GradeResponse>> {
  const { deps, session, record } = ctx;
  if (record.status === "reported") throw new HttpError(409, "Already reported");
  const wasSettled = isSettled(record) || record.status === "awaiting_prediction_result";
  const effective = record.bossId && action === "defer" ? "skip" : action;

  const next: MomentRecord = { ...record, status: STATUS[effective] };
  await deps.store.putMoment(next);
  if (session.engine.pendingMomentId === record.id) {
    await patchSession(deps, session.id, (latest) => ({
      engine: { ...latest.engine, pendingMomentId: latest.engine.pendingMomentId === record.id ? undefined : latest.engine.pendingMomentId },
    }));
  }
  await deps.store.logEvent({ at: deps.now(), anonId: session.anonId, sessionId: session.id, name: EVENT[effective], props: { momentId: record.id, type: record.type, concept: record.candidate.concept, boss: !!record.bossId } });

  if (record.bossId) {
    const advance = wasSettled ? null : await advanceBoss(deps, session, record.bossId, 0);
    return done(
      {
        moment: toMomentView(next),
        offerMC: false,
        xp: advance?.xp,
        boss: advance?.boss,
        continueWith: advance?.finished ? { sessionId: session.id, kind: "boss_result", bossId: record.bossId } : undefined,
      },
      advance?.background,
    );
  }
  // Reporting a moment the work already moved past shouldn't trigger another continuation.
  return done({ moment: toMomentView(next), offerMC: false, continueWith: wasSettled ? undefined : continueWork(ctx) });
}
/** Boss lifecycle: start (generate + verify questions), hits, and the outcome (design-plan §7.4). */
import type { StartBossResponse, GradeResponse } from "@/lib/contracts/api";
import type { LearningMomentInput } from "@/lib/contracts/moment";
import type { BossState, MomentRecord, Session } from "@/lib/contracts/session";
import type { XpAward } from "@/lib/contracts/stream";
import { toBossView, toMomentView } from "@/lib/views";
import type { BackgroundTask, HandlerResult, LearningDeps } from "./deps";
import { isSettled } from "./scores";
import { appendTranscript, patchSession } from "./sessionStore";
import { addChapter } from "./story";
import { recentMisconceptions, workSummary } from "./workSummary";
import { awardXp } from "./xp";

const BOSS_OUTCOME_LABEL = { flawless: "Flawless boss win", victory: "Boss defeated", retreat: "The boss retreats" } as const;

function distinctRecent(values: string[], limit: number): string[] {
  const out: string[] = [];
  for (let i = values.length - 1; i >= 0 && out.length < limit; i--) if (!out.includes(values[i])) out.push(values[i]);
  return out.reverse();
}

/** Concepts for the boss: practised since the last boss, else the most recent outcomes, else the sketch's radar. */
export function bossConcepts(session: Session): string[] {
  if (session.engine.conceptsSinceBoss.length) return [...new Set(session.engine.conceptsSinceBoss)];
  const recent = distinctRecent(session.engine.recentOutcomes.map((o) => o.concept), 4);
  if (recent.length) return recent;
  return (session.sketch?.conceptRadar ?? []).slice(0, 3).map((c) => c.concept);
}

/** Keeps verified questions; if verification rejects (or fails on) everything, keeps the originals rather than blocking the boss. */
async function verifiedQuestions(deps: LearningDeps, questions: LearningMomentInput[]): Promise<LearningMomentInput[]> {
  const checks = await Promise.all(
    questions.map((candidate) => deps.content.verifyMoment({ candidate }).catch(() => ({ ok: true as const }))),
  );
  const passed = questions.filter((_, i) => checks[i].ok);
  return passed.length ? passed : questions;
}

async function activeBoss(deps: LearningDeps, session: Session): Promise<StartBossResponse | null> {
  const open = [...session.engine.bosses].reverse().find((b) => !b.outcome);
  if (!open) return null;
  const boss = await deps.store.getBoss(session.id, open.id);
  if (!boss || boss.outcome) return null;
  const moments = (await deps.store.listMoments(session.id)).filter((m) => m.bossId === boss.id);
  if (moments.every(isSettled)) return null;
  return { boss: toBossView(boss, moments), moments: Object.fromEntries(moments.map((m) => [m.id, toMomentView(m)])) };
}

export async function startBoss(deps: LearningDeps, session: Session): Promise<HandlerResult<StartBossResponse>> {
  const existing = await activeBoss(deps, session);
  if (existing) return { body: existing, background: [] };

  const [transcript, allMoments] = await Promise.all([deps.store.getTranscript(session.id), deps.store.listMoments(session.id)]);
  const familiarity = session.intent.familiarity;
  const draft = await deps.content.generateBoss({
    intent: session.intent,
    familiarity,
    concepts: bossConcepts(session),
    workSummary: workSummary(transcript, 2000),
    misconceptions: recentMisconceptions(allMoments),
    targetDifficulty: deps.engine.targetDifficulty(undefined, "boss", familiarity, session.engine.recentOutcomes),
  });
  const questions = await verifiedQuestions(deps, draft.questions);

  const now = deps.now();
  const bossId = deps.newId();
  // createdAt offsets keep the questions in order (listMoments sorts by createdAt).
  const records: MomentRecord[] = questions.map((candidate, i) => ({
    id: deps.newId(),
    sessionId: session.id,
    createdAt: now + i,
    type: "boss",
    candidate,
    bossId,
    status: "awaiting_answer",
    mcOffered: false,
  }));
  const boss: BossState = {
    id: bossId,
    sessionId: session.id,
    name: draft.name,
    ascii: draft.ascii,
    intro: draft.intro,
    maxHp: records.length,
    hp: records.length,
    momentIds: records.map((r) => r.id),
    createdAt: now,
  };

  for (const r of records) await deps.store.putMoment(r);
  await deps.store.putBoss(boss);
  const concepts = [...new Set(questions.map((q) => q.concept))];
  await patchSession(deps, session.id, (latest) => ({
    engine: { ...latest.engine, bosses: [...latest.engine.bosses, { id: bossId, startedAt: now, concepts }] },
  }));
  await appendTranscript(deps, session.id, { kind: "boss", id: `boss-${bossId}`, bossId });
  await deps.store.logEvent({ at: now, anonId: session.anonId, sessionId: session.id, name: "boss_started", props: { bossId, questions: records.length, name: boss.name } });

  return {
    body: { boss: toBossView(boss, records), moments: Object.fromEntries(records.map((r) => [r.id, toMomentView(r)])) },
    background: [],
  };
}

export interface BossAdvance {
  boss: NonNullable<GradeResponse["boss"]>;
  xp?: XpAward;
  finished: boolean;
  background: BackgroundTask[];
}

/** Applies a hit (0, 0.5 or 1) after one of the boss's moments settles, finishing the boss when all are settled. */
export async function advanceBoss(deps: LearningDeps, session: Session, bossId: string, hit: number): Promise<BossAdvance | null> {
  const boss = await deps.store.getBoss(session.id, bossId);
  if (!boss) return null;
  const moments = (await deps.store.listMoments(session.id)).filter((m) => m.bossId === bossId);
  const updated: BossState = { ...boss, hp: Math.max(0, boss.hp - hit) };
  const nextMomentId = boss.momentIds.find((id) => moments.find((m) => m.id === id && !isSettled(m)));
  const done = !nextMomentId;
  const background: BackgroundTask[] = [];
  let xp: XpAward | undefined;

  if (done && !boss.outcome) {
    const hits = updated.maxHp - updated.hp;
    const outcome = deps.engine.bossOutcome(hits, updated.maxHp);
    updated.outcome = outcome;
    xp = await awardXp(deps, session.anonId, session.id, [{ kind: "boss_outcome", outcome }], BOSS_OUTCOME_LABEL[outcome]);
    await patchSession(deps, session.id, (latest) => ({
      engine: {
        ...latest.engine,
        conceptsSinceBoss: [],
        bosses: latest.engine.bosses.map((b) => (b.id === bossId ? { ...b, outcome } : b)),
      },
    }));
    await deps.store.logEvent({ at: deps.now(), anonId: session.anonId, sessionId: session.id, name: "boss_finished", props: { bossId, outcome, hits, maxHp: updated.maxHp } });
    background.push(async () => {
      await addChapter(deps, session.id, `boss:${bossId}`, "boss", outcome);
    });
  }
  await deps.store.putBoss(updated);

  return {
    boss: { bossId, hp: updated.hp, maxHp: updated.maxHp, done, outcome: updated.outcome, nextMomentId },
    xp,
    finished: done,
    background,
  };
}

/** Combines the hit award and the outcome award into the single XpAward a response carries. */
export function mergeAwards(a: XpAward | undefined, b: XpAward | undefined): XpAward | undefined {
  if (!a || !b) return a ?? b;
  const levelUp =
    a.levelUp && b.levelUp
      ? { from: a.levelUp.from, to: b.levelUp.to, rewards: [...a.levelUp.rewards, ...b.levelUp.rewards] }
      : (a.levelUp ?? b.levelUp);
  return { amount: a.amount + b.amount, reason: `${a.reason} + ${b.reason}`, level: b.level, ...(levelUp ? { levelUp } : {}) };
}
/** Injected dependencies so learning logic is testable with a MemoryStore and a mocked ContentApi. */
import type { ContentApi } from "@/lib/contracts/content";
